  "author": {
    "name": "YeomYuJun"
  },
  "userConfig": {
    "language": {
      "type": "string",
      "title": "Language",
      "description": "Panel and command language: auto, en or ko. auto reads a language key in settings if one is set, then LC_ALL and LANG, then English",
      "options": [
        "auto",
        "en",
        "ko"
      ],
      "default": "auto"
    }
  }
}
